def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            objects.append(cells)
    # Color alternate objects when ordered from right to left, starting at the rightmost.
    objects.sort(key=lambda cells: max(x for y, x in cells), reverse=True)
    out = [row[:] for row in grid]
    for i, cells in enumerate(objects):
        if i % 2 == 0:
            for y, x in cells:
                out[y][x] = 8
    return out
