def transform(grid):
    """Recolor every other 2x2 block of 2s from left to right.

    The leftmost block is recolored iff the total number of blocks is odd.
    """
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[y][x] == 2 for y in (r, r + 1) for x in (c, c + 1)):
                blocks.append((r, c))
    blocks.sort(key=lambda p: (p[1], p[0]))
    out = [row[:] for row in grid]
    start = 0 if len(blocks) % 2 else 1
    for i, (r, c) in enumerate(blocks):
        if i % 2 == start:
            for y in (r, r + 1):
                for x in (c, c + 1):
                    out[y][x] = 8
    return out
